{"command":"node -e "
const fs=require('fs');
const fc=require('/home/emsenn/561/operations/engineering/fars/agentic/tools/fars-core.js');
const path='operations/command/endeavor/records/plans/record-shape-refactor.md';
const c=fs.readFileSync(path,'utf8');
const fm=fc.parseFrontmatter(c);
console.log('Bytes:',c.length,'(~',Math.round(c.length/4),'tokens)');
console.log('Frontmatter keys:',Object.keys(fm).length);
console.log();

// Query 1: next task (topological sort, no predecessors)
const ord = fm.ordering || [];
const preds = new Set();
for (const [from,to] of ord) preds.add(to);
const ready = fm.tasks.filter(t => !preds.has(t));
console.log('Q: next-ready tasks:', ready);

// Query 2: critical path (longest chain)
const succ = {};
for (const [from,to] of ord) (succ[from]=succ[from]||[]).push(to);
function chainFrom(t){ const s=succ[t]||[]; if(!s.length) return [t]; return [t,...chainFrom(s[0])]; }
console.log('Q: critical path:', chainFrom(ready[0]).join(' → '));

// Query 3: what does this block
console.log('Q: blocks:', fm.blocks);

// Query 4: what phase does each task belong to
const taskPhase = {};
for (const [phase,tasks] of Object.entries(fm.phases||{})) for (const t of tasks) taskPhase[t]=phase;
console.log('Q: task→phase:', taskPhase);

// Query 5: gate for each milestone
console.log('Q: milestones:');
for (const [id,m] of Object.entries(fm.milestones||{})) console.log('  '+id+' @ '+m.at+' → '+m.gate);

// Query 6: serves chain
console.log('Q: serves:', fm.serves);
console.log('Q: part-of:', fm['part-of']);
console.log('Q: horizon:', fm.horizon);
console.log('Q: work-type:', fm['work-type']);
"","description":"Test queries against new plan shape"}

